#!/bin/bash
# Out-of-tree build of one host program against build_Release, using the in-tree example's flags.
set -e
: "${1:?usage: build_host.sh file.cpp}" "${TT_METAL_HOME:?source env.sh first}"
B=$TT_METAL_HOME/build_Release
clang++-20 -DENCHANTUM_ENABLE_MSVC_SPEEDUP=1 -DFMT_HEADER_ONLY=1 -DNTEST -DOVERRIDE_KERNEL_PREFIX=\"tt_metal/programming_examples/\" -DSPDLOG_COMPILED_LIB -DSPDLOG_FMT_EXTERNAL -DTRACY_ENABLE -DTRACY_IMPORTS -DTRACY_TIMER_FALLBACK -DTT_ENABLE_LIGHT_METAL_TRACE=1 -DTT_UMD_BUILD_SIMULATION -I$TT_METAL_HOME/tt_stl/. -I$TT_METAL_HOME/tt_metal/api -I$TT_METAL_HOME/build_Release/tt_metal/api -I$TT_METAL_HOME/tt_metal/hostdevcommon/api -I$TT_METAL_HOME/tt_metal/programming_examples/matmul/matmul_common -isystem $TT_METAL_HOME/.cpmcache/reflect/f93e77475670eaeacf332927dfe8b50e3f3812e0 -isystem $TT_METAL_HOME/.cpmcache/enchantum/2fb7ab238e36c101b9848892ddb6382276b65837/enchantum/include -isystem $TT_METAL_HOME/.cpmcache/nlohmann_json/798e0374658476027d9723eeb67a262d0f3c8308/include -isystem $TT_METAL_HOME/.cpmcache/fmt/69912fb6b71fcb1f7e5deca191a2bb4748c4e7b6/include -isystem $TT_METAL_HOME/.cpmcache/tt-logger/d2339ce68562cae34cd95f3fece7fd94eb0529b7/include -isystem $TT_METAL_HOME/.cpmcache/spdlog/b1c2586bb5c35a7929362e87f62433eb68206873/include -isystem $TT_METAL_HOME/tt_metal/third_party/umd/tt-umd-workload/api -isystem $TT_METAL_HOME/tt_metal/third_party/umd/tt-umd/api -isystem $TT_METAL_HOME/tt_metal/third_party/umd/tt-umd-utils/api -isystem $TT_METAL_HOME/tt_metal/third_party/tracy/public -isystem $TT_METAL_HOME/build_Release/generated/profiler -O3 -DNDEBUG -std=c++20 -fPIE -fno-omit-frame-pointer -fsized-deallocation -gz -march=x86-64-v3 -fPIC -pipe -fvisibility-inlines-hidden -Wall -Wconditional-uninitialized -Wno-deprecated-declarations -Xclang -fno-pch-timestamp -Wunused-parameter -Wno-c++11-narrowing -Wno-int-to-pointer-cast -Werror -c "$1" -o "${1%.cpp}.o"
echo "compiled ${1%.cpp}.o"
clang++-20 -O3 -rdynamic -fuse-ld=lld "${1%.cpp}.o" -o "${1%.cpp}" -Wl,-rpath,$B/tt_metal:$B/tt_stl:$B/lib:$B/tt_metal/third_party/umd/lib \
  $B/tt_metal/libtt_metal.so $B/tt_stl/libtt_stl.so $B/lib/libtracy.so.0.14.1 $B/tt_metal/third_party/umd/lib/libtt-umd.so.0.9.15 -lhwloc \
  $B/_deps/yaml-cpp-build/libyaml-cpp.a $B/tt_metal/third_party/umd/tt-kmd-lib/libtt-kmd-lib.a $B/tt_metal/third_party/umd/tt-umd-utils/libtt-umd-utils.a \
  $B/_deps/spdlog-build/libspdlog.a $B/_deps/flatbuffers-build/libflatbuffers.a $B/_deps/nanomsg-build/libnng.a -lnsl -latomic $B/_deps/libuv-build/libuv.a -ldl -lrt -lpthread -lm
